"""Explain single-waiter registration, loop decisions and wake ordering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1441': ('호출 벨 옆에 기다리는 사람의 이름을 한 명만 적는 칸이 있습니다. 이름이 적혀 있어도 그 사람이 벌써 잠들었는지, 아직 준비 여부를 살피는지는 알 수 없습니다.', '한 명의 대기자를 가리키는 rcuwait와 순간 상태 조회의 한계를 이해합니다.', 'task 칸에 NULL → A의 주소 → NULL을 적으세요. 가운데 칸 아래에는 “조건 확인 중일 수도 있고 잠든 중일 수도 있음”을 쓰세요.', ['태스크(task)는 커널이 실행을 관리하는 작업입니다. task_struct는 그 작업의 정보를 담은 구조체입니다. rcuwait 안에는 그 구조체를 가리키는 task 포인터 한 개가 있습니다. 여러 명을 넣는 배열이나 줄 전체를 담는 목록은 없습니다.', '포인터는 대상의 위치를 가리키는 값입니다. NULL은 여기서 등록된 대상이 없다는 표시입니다. 새 rcuwait를 초기화하면 task는 NULL입니다. 기다릴 작업이 자신을 등록하면 그 작업의 주소가 들어갑니다.', '등록은 실제로 잠든 시간에만 유지되는 것이 아닙니다. 기다릴 필요가 있는지 조건을 확인하는 동안에도 등록되어 있습니다. 따라서 이름표를 보고 곧바로 “지금 자고 있다”라고 결론 내리면 틀립니다.', 'rcuwait_active는 rcu_access_pointer로 task 값을 살펴봅니다. 앞의 !!는 NULL이면 0, NULL이 아니면 1로 정리하는 표기입니다. 첫 !가 참·거짓을 뒤집고 둘째 !가 다시 뒤집어 존재 여부를 0이나 1로 나타냅니다.', '이 조회 자체에는 등록을 막거나 다른 작업과 차례를 맞추는 잠금이 없습니다. 읽은 직후 상태가 바뀔 수도 있습니다. active=1만 보고 잠금 소유권을 얻었다거나 포인터의 대상이 언제까지나 살아 있다고 판단해서는 안 됩니다.', '한 rcuwait에는 동시에 대기자 한 명이라는 규칙을 지켜야 합니다. A와 B가 같은 칸에 자기 주소를 쓰면 A의 기록이 B로 덮일 수 있습니다. 호출자는 등록과 완료가 겹치지 않도록 외부 규약을 마련합니다. RCU라는 이름이 여러 대기자를 위한 공간을 늘려 주지는 않습니다.'], [('rcuwait가 직접 저장하는 대기자 기록은?', ['여러 작업을 담는 배열이에요', '작업을 가리키는 포인터 한 개예요'], '구조체에는 task 포인터 하나만 있습니다. 여러 사람을 넣는 배열이나 목록이 아니므로 같은 rcuwait에 여러 대기자를 동시에 등록하면 안 됩니다.'), ('active가 1이면 그 작업은 반드시 지금 잠들어 있을까요?', ['아니요. 아직 기다릴 조건을 확인 중일 수도 있어요', '네. 무조건 잠들어 있다는 증거예요'], '대기 등록은 조건 확인 중에도 유지됩니다. active는 포인터의 존재를 그 순간 확인할 뿐 실제 수면 상태나 앞으로의 상태까지 보장하지 않습니다.')]), 'os1442': ('한 칸짜리 예약표에 내 이름을 적는 것은, 다른 사람도 같은 칸에 쓰지 못하게 문을 잠그는 것과 다릅니다. 이름 공개와 차례 정하기는 따로 필요합니다.', 'current 등록과 RCU 공개가 다중 대기자의 상호 배제를 대신하지 않는 이유를 배웁니다.', 'A 등록: task=A → B가 규칙 없이 등록: task=B → A의 기록을 찾을 수 없음을 그리세요. 이를 올바른 다중 대기열로 착각하지 마세요.', ['prepare_to_rcuwait는 기다리기 전 자신의 작업을 등록하는 함수입니다. current는 지금 이 코드를 실행하는 태스크를 가리킵니다. 부모 태스크나 다음에 실행할 태스크를 자동으로 골라 주는 이름이 아닙니다.', '본문은 rcu_assign_pointer(w->task,current)입니다. w->task는 w가 가리키는 rcuwait의 task 항목입니다. rcu_assign_pointer는 RCU의 규칙에 맞게 이 포인터를 다른 실행 흐름에 공개하는 도구입니다.', '공개란 깨우는 쪽이 어떤 작업에 연락해야 하는지 볼 수 있도록 주소를 놓는 일입니다. 준비된 주소를 올바르게 전달하는 일과 두 작업이 같은 칸을 동시에 차지하지 못하도록 하는 일은 다릅니다.', 'A가 등록한 뒤 A의 대기가 끝나기도 전에 B가 자기 주소를 쓰면 칸에는 B만 남을 수 있습니다. 더구나 A가 완료하면서 칸을 NULL로 만들면 B의 등록까지 지워질 수 있습니다. 원자적으로 주소를 저장하더라도 이런 전체 사용 순서는 저절로 해결되지 않습니다.', '헤더는 task에 쓰는 prepare와 finish, 대기 매크로의 사용을 호출자가 적절한 잠금 규약으로 직렬화하라고 요구합니다. 직렬화는 충돌하는 사용을 차례대로 이루어지게 하는 뜻입니다. 잠들 수 있는 대기 전체를 아무 spinlock 아래 두라는 뜻은 아닙니다. 대기 문맥에 맞는 외부 규약이 필요합니다.', '공통 대기 매크로는 반복문에 들어가기 전에 prepare를 하고, 반복을 끝내면 finish로 등록을 지웁니다. 조건이 이미 맞아 실제로 잠들지 않더라도 등록과 완료를 거칠 수 있습니다. prepare는 준비 단계이며 그 자체가 schedule로 잠드는 명령은 아닙니다.'], [('prepare_to_rcuwait가 기록하는 current는 누구일까요?', ['항상 부모 작업이에요', '지금 이 함수를 실행하는 작업이에요'], 'current는 현재 실행 중인 태스크를 가리킵니다. 코드가 그 값을 그대로 등록하므로 부모를 선택하거나 다른 대기자를 검색하는 동작은 아닙니다.'), ('rcu_assign_pointer만 있으면 여러 대기자의 등록 순서도 자동으로 안전해질까요?', ['아니요. 호출자가 서로 겹치지 않도록 규약을 마련해야 해요', '네. 한 칸이 자동으로 여러 명의 대기열이 돼요'], 'RCU 공개는 포인터 전달 규칙입니다. 한 칸에 두 사람이 등록하는 전체 사용을 서로 배제하지 않으므로 별도 규약이 필요합니다. 여러 명을 저장할 목록이 생기는 것도 아닙니다.')]), 'os1443': ('음식이 준비됐는지 먼저 보고, 아니면 기다림을 중단해야 하는지 확인합니다. 누가 불렀다고 음식이 무조건 준비된 것은 아니므로 다시 확인합니다.', '대기 반복문의 조건·중단 신호·잠들기 순서를 따라갑니다.', '조건 참+중단 신호 있음 → 조건으로 종료, 조건 거짓+허용 신호 있음 → -EINTR, 둘 다 아님 → 기다린 뒤 재검사를 적으세요.', ['여기서는 시간 제한 없는 rcuwait_wait_event를 중심으로 봅니다. 매크로는 코드를 펼쳐 넣는 규칙입니다. 이 대기 매크로는 반환값을 0으로 준비하고 현재 작업을 등록한 뒤 반복문으로 들어갑니다.', '반복할 때마다 먼저 set_current_state로 대기 상태를 설정합니다. 이는 즉시 잠들었다는 뜻이 아닙니다. 곧바로 condition, 즉 기다리던 조건이 맞는지 확인합니다. 맞으면 break로 반복을 끝냅니다.', '조건이 거짓일 때만 signal_pending_state를 확인합니다. signal은 작업에게 전달되는 알림입니다. 어떤 알림이 기다림을 중단할 수 있는지는 지정한 대기 상태에 따라 다릅니다. 모든 상태에서 모든 신호가 항상 중단시키는 것은 아닙니다.', '이 대기에서 중단 가능한 신호가 있다면 반환값을 -EINTR로 바꾸고 반복을 끝냅니다. -EINTR은 기다림이 신호로 중단됐다는 오류 코드입니다. 조건과 신호를 모두 확인할 수 있는 상황에서는 앞에 있는 조건 검사가 먼저입니다.', '조건도 아직 거짓이고 허용되는 중단 신호도 없으면 schedule로 CPU를 다른 작업에 양보합니다. 나중에 돌아오면 반복 위로 가서 조건을 다시 봅니다. 깨우기는 다시 확인할 기회이며 성공 조건을 대신하지 않습니다. 조건식은 여러 번 평가되어도 맞도록 작성해야 합니다.', '반복을 끝낸 뒤에는 finish_rcuwait가 task를 NULL로 만들고 현재 작업 상태를 TASK_RUNNING으로 되돌립니다. 조건 성공이든 신호 중단이든 이 정리를 거칩니다. 여기서 성공 경로는 준비한 0을 유지하지만, 시간 제한 버전의 반환값은 별도 규칙으로 읽어야 합니다.'], [('조건이 참이고 중단 가능한 신호도 있다면 무엇을 먼저 판정할까요?', ['무조건 신호 오류 -EINTR부터 골라요', '앞에 있는 조건 성공을 먼저 판정해요'], '코드는 condition을 먼저 확인하고 참이면 바로 반복을 끝냅니다. 신호 검사는 조건이 거짓일 때만 도달하므로 신호가 항상 우선이라는 답은 틀립니다.'), ('조건은 처음 한 번만 읽고 그 값으로 계속 기다릴까요?', ['아니요. 기다렸다 돌아온 뒤 다시 확인해요', '네. 첫 번째 값을 끝까지 사용해요'], 'for 반복문 안에 조건 검사가 있습니다. 깨어났어도 조건이 아직 맞지 않으면 다시 기다릴 수 있으므로, 평가를 한 번만 한다고 가정하면 안 됩니다.')]), 'os1444': ('기다리는 사람은 “나 여기 있어요”를 적고 준비 여부를 봅니다. 준비하는 사람은 “준비됐어요”를 적고 누구를 부를지 봅니다. 서로 상대의 새 표시를 놓치면 준비가 끝나도 아무도 부르지 않는 문제가 생깁니다.', '대기자와 깨우는 쪽의 두 기록·두 확인 순서를 이해합니다.', '왼쪽: task 공개 → A 배리어 → 조건 읽기. 오른쪽: 조건 변경 → B 배리어 → task 읽기를 그리세요. 각각 무엇을 쓰고 무엇을 읽는지 색을 달리 표시하세요.', ['waiter는 기다리는 작업, waker는 깨우는 쪽입니다. 대기자는 먼저 task에 자기 주소를 공개합니다. 이어 set_current_state로 대기 상태를 정한 뒤 기다리던 조건을 읽습니다.', 'set_current_state에는 원문에서 A라고 부른 메모리 배리어가 포함됩니다. 배리어는 잠깐 쉬는 명령이 아니라 여러 CPU가 메모리 접근의 순서를 맞추게 하는 장치입니다. 여기서는 자기 등록과 이후 조건 관측을 연결합니다.', '깨우는 쪽은 먼저 공유 조건을 바꾸고 rcuwait_wake_up을 호출하는 규칙을 따릅니다. 이 함수 안의 smp_mb가 B 배리어입니다. 그 뒤 rcu_dereference로 등록된 task를 읽어 대상이 있으면 wake_up_process를 호출합니다.', '위험한 상황을 생각해 보세요. waiter는 예전 조건인 거짓만 보고 잠들려 하고, waker도 예전 task 값인 NULL만 보고 아무도 없다고 판단하면 필요한 깨우기를 놓칩니다. A와 B의 짝은 원문의 올바른 등록·상태·조건 규약 안에서 이런 서로 놓침을 막는 데 쓰입니다.', '그래서 기다리는 쪽의 상태 설정을 단순한 일반 변수 대입으로 바꾸거나, 깨우는 함수를 부른 뒤에야 조건을 바꾸면 같은 보장을 기대할 수 없습니다. 조건을 바꾸는 코드와 wake 함수는 다른 곳에 있더라도 순서로 이어져야 합니다.', 'RCU 읽기 보호는 깨우는 쪽이 task 포인터를 따라 작업에 접근할 때 사용됩니다. 메모리 순서와 포인터 수명, 한 명만 등록한다는 외부 규약은 각각 지켜야 합니다. 종이에 순서를 그리는 것은 이해를 돕지만 실제 CPU의 모든 동시 실행을 시험했다는 뜻은 아닙니다.'], [('기다리는 쪽은 A 배리어를 거친 뒤 무엇을 읽을까요?', ['여러 태스크 배열의 길이를 읽어요', '기다리던 조건이 맞는지 읽어요'], '대기자는 자기 task를 공개하고 상태를 설정한 뒤 condition을 검사합니다. rcuwait에 여러 태스크 배열은 없으므로 배열 길이를 읽는 흐름이 아닙니다.'), ('깨우는 쪽은 B 배리어 뒤 무엇을 확인할까요?', ['등록된 task 포인터를 읽어요', '조건을 강제로 거짓으로 바꿔요'], '조건 변경에 뒤이어 배리어를 거치고 누구를 깨울지 task 포인터를 읽습니다. wake 함수가 조건을 거짓으로 만드는 것이 아니며 조건 변경은 호출하는 쪽의 규약과 연결됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_356.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
